<?php
require_once __DIR__ . '/../includes/auth.php';$u=require_role(['admin','superadmin']);$rows=$pdo->query("SELECT r.*,a.full_name AS owner FROM recovered_items r LEFT JOIN accounts a ON a.id=r.intended_owner_id ORDER BY r.created_at DESC")->fetchAll();page_header('Recovered Items');?><h1>Recovered Items Awaiting Claims</h1><div class="table-wrap"><table><tr><th>Item</th><th>Location</th><th>Date Found</th><th>Intended Owner</th><th>Claim Status</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['item_name'])?></td><td><?=e($r['location_found'])?></td><td><?=e($r['date_found'])?></td><td><?=e($r['owner']??'Not assigned')?></td><td><?=e($r['recovery_status'])?></td><td><?php if($r['recovery_status']!=='Claimed'):?><form method="post" action="claim-item.php"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="small">Mark Claimed</button></form><?php endif;?></td></tr><?php endforeach;?></table></div><?php page_footer();?>
